// TopStories is the resolver for the topStories field.
func (r *queryResolver) TopStories(ctx context.Context, offset *int, limit *int) ([]*model.Story, error) {
	log.Printf("loading topstories, offset:%d limit:%d", *offset, *limit)

	stories, err := r.topStoriesCache.get()
	if err != nil {
		log.Printf("err: %v", err)
		return nil, err
	}

	start := *offset
	end := start + *limit
	if start >= len(stories) {
		return []*model.Story{}, nil
	}
	if end > len(stories) {
		end = len(stories)
	}

	return stories[start:end], nil
}

